<?php session_start(); require "db.php"; if ($_SERVER["REQUEST_METHOD"] !== "POST") { header("Location: index.html"); exit; } $username = trim($_POST["username"] ?? ""); $password = $_POST["password"] ?? ""; if ($username === "" || $password === "") { die("Please enter your username and password."); } $stmt = $pdo->prepare( "SELECT id, username, password_hash FROM users WHERE username = ? LIMIT 1" ); $stmt->execute([$username]); $user = $stmt->fetch(); if (!$user || !password_verify($password, $user["password_hash"])) { die("Incorrect username or password."); } // Create a new session ID after successful authentication session_regenerate_id(true); $_SESSION["user_id"] = $user["id"]; $_SESSION["username"] = $user["username"]; // Send the user to the dashboard header("Location: dashboard.php"); exit; ?>